-- The database schema of schemaVersion 1 (first release, commit 3f95340),
-- read from sqlite_master of a fresh AppDatabase. Used by
-- test/data/migration_test.dart to create an old database. Never change it.
CREATE TABLE "foods" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "source" INTEGER NOT NULL, "barcode" TEXT NULL UNIQUE, "name" TEXT NOT NULL, "brand" TEXT NULL, "quantity_label" TEXT NULL, "is_liquid" INTEGER NOT NULL DEFAULT 0 CHECK ("is_liquid" IN (0, 1)), "serving_size" REAL NULL, "serving_label" TEXT NULL, "kcal" REAL NULL, "fat" REAL NULL, "saturated_fat" REAL NULL, "carbs" REAL NULL, "sugars" REAL NULL, "fibre" REAL NULL, "protein" REAL NULL, "salt" REAL NULL, "nutri_score" TEXT NULL, "nova_group" INTEGER NULL, "categories" TEXT NULL, "image_url" TEXT NULL, "completeness" REAL NULL, "is_favourite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favourite" IN (0, 1)), "last_used_at" INTEGER NULL, "last_viewed_at" INTEGER NULL, "fetched_at" INTEGER NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "meal_slots" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "built_in" TEXT NULL, "custom_name" TEXT NULL, "position" INTEGER NOT NULL, "is_hidden" INTEGER NOT NULL DEFAULT 0 CHECK ("is_hidden" IN (0, 1)), "start_minute" INTEGER NULL);
CREATE TABLE "diary_entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "day" TEXT NOT NULL, "meal_slot_id" INTEGER NOT NULL REFERENCES meal_slots (id), "food_id" INTEGER NULL REFERENCES foods (id) ON DELETE SET NULL, "name" TEXT NOT NULL, "brand" TEXT NULL, "amount" REAL NOT NULL, "is_liquid" INTEGER NOT NULL DEFAULT 0 CHECK ("is_liquid" IN (0, 1)), "serving_label" TEXT NULL, "kcal" REAL NULL, "fat" REAL NULL, "saturated_fat" REAL NULL, "carbs" REAL NULL, "sugars" REAL NULL, "fibre" REAL NULL, "protein" REAL NULL, "salt" REAL NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "user_goal" ("id" INTEGER NOT NULL, "kcal" INTEGER NOT NULL, "protein" REAL NULL, "carbs" REAL NULL, "fat" REAL NULL, "sex" INTEGER NULL, "age" INTEGER NULL, "height_cm" REAL NULL, "weight_kg" REAL NULL, "activity" INTEGER NULL, "goal_type" INTEGER NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
